package com.stripe.mpp.server;

import com.stripe.mpp.Challenge;
import com.stripe.mpp.Credential;
import com.stripe.mpp.error.ParseException;

import java.util.ArrayList;
import java.util.List;

/**
 * Handles multi-method payment challenges. Create via {@link com.stripe.mpp.Mpp#compose}.
 *
 * <pre>{@code
 * ComposedHandler composed = Mpp.compose(
 *     tempoHandler.chargeDescriptor(tempoIntent, "1.000000", "USDC", "0xRecipient"),
 *     stripeHandler.chargeDescriptor(stripeIntent, "1.00", "usd", null)
 * );
 *
 * VerifyResult result = composed.charge(request.getHeader("Authorization"));
 * if (result instanceof VerifyResult.Challenged) {
 *     List<String> headers = Challenge.toWwwAuthenticate(
 *         ((VerifyResult.Challenged) result).challenges()
 *     );
 *     headers.forEach(h -> response.addHeader("WWW-Authenticate", h));
 * } else {
 *     VerifyResult.Verified verified = (VerifyResult.Verified) result;
 *     response.setHeader("Payment-Receipt", verified.receipt().toPaymentReceipt());
 * }
 * }</pre>
 */
public final class ComposedHandler {
    private final List<ChargeDescriptor> descriptors;

    public ComposedHandler(List<ChargeDescriptor> descriptors) {
        if (descriptors == null || descriptors.isEmpty()) {
            throw new IllegalArgumentException("At least one ChargeDescriptor is required");
        }
        this.descriptors = List.copyOf(descriptors);
    }

    /**
     * Verify the Authorization header against all composed methods, or issue challenges for all.
     *
     * <p>If the credential targets a recognized method, only that method is verified.
     * If verification fails or no credential is present, fresh challenges are issued for every method.
     */
    public VerifyResult charge(String authorization) {
        return charge(authorization, null, false);
    }

    /** Verify or challenge all composed methods with binding to the current request body. */
    public VerifyResult charge(String authorization, Object body) {
        return charge(authorization, body, true);
    }

    private VerifyResult charge(String authorization, Object body, boolean bodyOverride) {
        if (authorization != null) {
            String paymentScheme = Verify.extractPaymentScheme(authorization);
            if (paymentScheme != null) {
                try {
                    Credential credential = Credential.fromAuthorization(paymentScheme);
                    String credMethod = credential.challenge().method();
                    for (ChargeDescriptor d : descriptors) {
                        if (d.handler().method().name().equals(credMethod)) {
                            VerifyResult result = d.handler().charge(
                                authorization, d.intent(), d.amount(), d.currency(),
                                d.recipient(), d.description(), d.meta(), d.expires(),
                                bodyOverride ? body : d.body()
                            );
                            if (result instanceof VerifyResult.Verified) {
                                return result;
                            }
                            break;
                        }
                    }
                } catch (ParseException e) {
                    // fall through to re-challenge
                }
            }
        }

        return new VerifyResult.Challenged(buildChallenges(body, bodyOverride));
    }

    private List<Challenge> buildChallenges(Object body, boolean bodyOverride) {
        List<Challenge> challenges = new ArrayList<>(descriptors.size());
        for (ChargeDescriptor d : descriptors) {
            challenges.add(Verify.createChallenge(
                d.handler().method().name(), d.intent(), d.handler().buildRequest(d),
                d.handler().realm(), d.handler().secretKey(),
                d.description(), d.meta(), d.expires(), bodyOverride ? body : d.body()
            ));
        }
        return challenges;
    }
}

# mpp-java

Java SDK for the [**Machine Payments Protocol**](https://mpp.dev)

> **Note:** This is an experimental SDK and the API is subject to change.

[![License](https://img.shields.io/badge/license-MIT-blue.svg)](LICENSE)

## Installation

### Gradle

```groovy
implementation 'com.stripe:mpp-java:0.1.6'
```

### Maven

```xml
<dependency>
    <groupId>com.stripe</groupId>
    <artifactId>mpp-java</artifactId>
    <version>0.1.6</version>
</dependency>
```

## Breaking change: custom Tempo memos

`TempoMethod.Builder.memo(...)` and `Method.memo()` have been removed. Remove these
configurations and overrides; clients use automatic challenge-bound attribution
memos. Direct Tempo verification rejects explicit memos in payment requests.

## Usage

### Testnet

```java
// Token contract address for the currency you accept
String currency = TempoDefaults.TESTNET_PATH_USD;

// Your server's realm — identifies this API in payment challenges
String realm = "api.example.com";

// Secret used to secure payment challenges
// https://mpp.dev/protocol/challenges#challenge-binding
String mppSecret = [REDACTED]"MPP_SECRET_KEY");

TempoMethod tempo = TempoMethod.of().testnet().build();
MppHandler mppHandler = Mpp.create(tempo, realm, mppSecret);

// In your HTTP handler: verify if MPP payment has been provided
VerifyResult result = mppHandler.charge(
    request.getHeader("Authorization"),
    ChargeRequest.of(tempo.chargeIntent(), "0.50", currency, "0xYourWalletAddress")
        .description("Paid endpoint")
);

if (result instanceof VerifyResult.Challenged) {
    response.setHeader("WWW-Authenticate",
        ((VerifyResult.Challenged) result).challenge().toWwwAuthenticate());
    response.setStatus(402);
} else {
    VerifyResult.Verified verified = (VerifyResult.Verified) result;
    response.setHeader("Payment-Receipt", verified.receipt().toPaymentReceipt());
    // serve your content
}
```

Test the endpoint using the [Tempo CLI](https://mpp.dev):

```sh
tempo request https://your-api.com/your-endpoint
```

### Tempo API relay

Delegate Moderato charge validation and broadcast to Tempo API by adding the server-side API key
to the method builder:

```java
TempoMethod tempo = TempoMethod.of()
    .testnet()
    .relay(System.getenv("TEMPO_API_KEY"))
    .build();
```

`MppHandler.charge(...)` validates immediately before broadcast. Applications that expose those
phases separately can use `validateCredential(...)` for a non-mutating pre-check and
`broadcastCredential(...)` when accepting the payment. Pass the same request body to both calls;
the latter always re-validates the credential and body digest before broadcasting.

For requests with a body, pass the exact body bytes (or the exact string received) through
`ChargeRequest.body(...)`. The SDK includes its RFC 9530 SHA-256 digest in the challenge and
rejects a credential if the retried body differs. Omitting the body indicates that the request
has no body; body presence and digest presence are checked fail-closed.

```java
byte[] requestBody = request.getInputStream().readAllBytes();
ChargeRequest charge = ChargeRequest
    .of(tempo.chargeIntent(), "0.50", currency, "0xYourWalletAddress")
    .description("Paid endpoint")
    .body(requestBody);
VerifyResult result = mppHandler.charge(request.getHeader("Authorization"), charge);
```

See the runnable [Tempo relay example](examples/tempo-relay).

### Mainnet

```java
// Token contract address for the currency you accept
String currency = TempoDefaults.MAINNET_USDC;

// Your server's realm — identifies this API in payment challenges
String realm = "api.example.com";

// Secret used to secure payment challenges
// https://mpp.dev/protocol/challenges#challenge-binding
String mppSecret = [REDACTED]"MPP_SECRET_KEY");

TempoMethod tempo = TempoMethod.of().build(); // mainnet is the default
MppHandler mppHandler = Mpp.create(tempo, realm, mppSecret);

// In your HTTP handler: verify if MPP payment has been provided
VerifyResult result = mppHandler.charge(
    request.getHeader("Authorization"),
    ChargeRequest.of(tempo.chargeIntent(), "0.50", currency, "0xYourWalletAddress")
        .description("Paid endpoint")
);

if (result instanceof VerifyResult.Challenged) {
    response.setHeader("WWW-Authenticate",
        ((VerifyResult.Challenged) result).challenge().toWwwAuthenticate());
    response.setStatus(402);
} else {
    VerifyResult.Verified verified = (VerifyResult.Verified) result;
    response.setHeader("Payment-Receipt", verified.receipt().toPaymentReceipt());
    // serve your content
}
```

### Replay protection

The server "claims" on-chain transaction hashes in a `Store` when they are presented by the client so the same payment cannot be redeemed twice. The SDK ships with an in-memory `Store` by default which is suitable for development/single-process use, but will not work in serverless or multi-server environments.

Redis or another atomic, durable store is recommended in production.

```java
TempoMethod tempo = TempoMethod.of()
    .store(key -> redis.setnx(key, "1") == 1)  // shared across every instance
    .build();
```

The Tempo Relay performs its own replay protection.

## Releasing

1. Create a release branch and update `VERSION_NAME` in `gradle.properties` and the version references in this README.
2. Open a PR and let CI pass.
3. Merge the PR to `main`.
4. Tag the merge commit and push the tag:
   ```sh
   git checkout main && git pull
   git tag v<version>
   git push origin v<version>
   ```
5. The [Publish workflow](.github/workflows/publish.yml) will automatically build, test across Java 11/17/21, and publish to Maven Central.
6. Verify the artifact appears on [Maven Central](https://central.sonatype.com/artifact/com.stripe/mpp-java).

package com.stripe.mpp.methods.stripe;

import com.stripe.StripeClient;
import com.stripe.exception.StripeException;
import com.stripe.model.PaymentIntent;
import com.stripe.net.RequestOptions;
import com.stripe.param.PaymentIntentCreateParams;
import com.stripe.mpp.error.VerificationFailedException;

import java.util.List;
import java.util.Map;
import java.util.Objects;

/**
 * Thin wrapper around the Stripe Java SDK, injected into {@link StripeChargeIntent} so
 * tests can stub the API call without real credentials.
 */
class StripeApi {

    static final class Result {
        private final String id;
        private final String status;

        Result(String id, String status) {
            this.id = id;
            this.status = status;
        }

        String id() { return id; }
        String status() { return status; }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Result)) return false;
            Result result = (Result) o;
            return Objects.equals(id, result.id)
                && Objects.equals(status, result.status);
        }

        @Override
        public int hashCode() {
            return Objects.hash(id, status);
        }

        @Override
        public String toString() {
            return "Result[id=" + id + ", status=" + status + "]";
        }
    }

    Result createAndConfirm(
        String secretKey,
        long amountMinorUnits,
        String currency,
        String spt,
        List<String> paymentMethodTypes,
        Map<String, String> metadata,
        String challengeId
    ) {
        try {
            StripeClient client = new StripeClient(secretKey);

            PaymentIntentCreateParams.Builder builder = PaymentIntentCreateParams.builder()
                .setAmount(amountMinorUnits)
                .setCurrency(currency)
                .setConfirm(true)
                .addAllPaymentMethodType(paymentMethodTypes)
                .putExtraParam("shared_payment_granted_token", spt);

            if (metadata != null && !metadata.isEmpty()) {
                builder.putAllMetadata(metadata);
            }

            RequestOptions options = RequestOptions.builder()
                .setIdempotencyKey(buildIdempotencyKey(challengeId, spt))
                .build();

            PaymentIntent pi = client.paymentIntents().create(builder.build(), options);
            return new Result(pi.getId(), pi.getStatus());

        } catch (StripeException e) {
            throw new VerificationFailedException(e.getMessage());
        }
    }

    static String buildIdempotencyKey(String challengeId, String spt) {
        return "mpp_" + challengeId + "_" + spt;
    }
}

package com.stripe.mpp;

import org.junit.jupiter.api.Test;

import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;

class BodyDigestTest {

    @Test
    void computeStartsWithAlgorithmPrefix() {
        String digest = BodyDigest.compute("hello world");
        assertThat(digest).startsWith("sha-256=");
    }

    @Test
    void computeIsIdempotent() {
        String d1 = BodyDigest.compute("test body");
        String d2 = BodyDigest.compute("test body");
        assertThat(d1).isEqualTo(d2);
    }

    @Test
    void computeDiffersForDifferentInputs() {
        String d1 = BodyDigest.compute("body one");
        String d2 = BodyDigest.compute("body two");
        assertThat(d1).isNotEqualTo(d2);
    }

    @Test
    void verifyMatchesComputed() {
        String body = "the request body";
        String digest = BodyDigest.compute(body);
        assertThat(BodyDigest.verify(digest, body)).isTrue();
    }

    @Test
    void verifyRejectsWrongDigest() {
        assertThat(BodyDigest.verify("sha-256=AAAA", "body")).isFalse();
    }

    @Test
    void computeWorksForMap() {
        Map<String, Object> body = Map.of("key", "value");
        String digest = BodyDigest.compute(body);
        assertThat(digest).startsWith("sha-256=");
        assertThat(BodyDigest.verify(digest, body)).isTrue();
    }
}

package com.stripe.mpp;

import com.stripe.mpp.server.VerifyResult;
import com.stripe.mpp.server.ValidationResult;
import org.junit.jupiter.api.Test;

import java.time.Instant;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;

class ValueTypesTest {

    @Test
    void challengePreservesRecordStyleApiAndValueSemantics() {
        Map<String, Object> request = Map.of("amount", "10.00");
        Map<String, Object> opaque = Map.of("order", "order-123");
        Challenge challenge = new Challenge(
            "id",
            "tempo",
            "charge",
            request,
            "api.example.com",
            "request-b64",
            "sha-256=abc",
            "2099-01-01T00:00:00Z",
            "description",
            opaque
        );
        Challenge equivalent = new Challenge(
            "id",
            "tempo",
            "charge",
            request,
            "api.example.com",
            "request-b64",
            "sha-256=abc",
            "2099-01-01T00:00:00Z",
            "description",
            opaque
        );

        assertThat(challenge.id()).isEqualTo("id");
        assertThat(challenge.method()).isEqualTo("tempo");
        assertThat(challenge.intent()).isEqualTo("charge");
        assertThat(challenge.request()).isSameAs(request);
        assertThat(challenge.realm()).isEqualTo("api.example.com");
        assertThat(challenge.requestB64()).isEqualTo("request-b64");
        assertThat(challenge.digest()).isEqualTo("sha-256=abc");
        assertThat(challenge.expires()).isEqualTo("2099-01-01T00:00:00Z");
        assertThat(challenge.description()).isEqualTo("description");
        assertThat(challenge.opaque()).isSameAs(opaque);
        assertThat(challenge.opaqueRaw()).isEqualTo(
            ChallengeId.b64urlEncode(Json.compact(opaque))
        );
        assertThat(challenge).isEqualTo(equivalent).hasSameHashCodeAs(equivalent);
    }

    @Test
    void challengeEchoPreservesRecordStyleApiAndValueSemantics() {
        Map<String, Object> opaque = Map.of("order", "order-123");
        ChallengeEcho echo = new ChallengeEcho(
            "id",
            "api.example.com",
            "tempo",
            "charge",
            "request-b64",
            "2099-01-01T00:00:00Z",
            "sha-256=abc",
            opaque
        );
        ChallengeEcho equivalent = new ChallengeEcho(
            "id",
            "api.example.com",
            "tempo",
            "charge",
            "request-b64",
            "2099-01-01T00:00:00Z",
            "sha-256=abc",
            opaque
        );

        assertThat(echo.id()).isEqualTo("id");
        assertThat(echo.realm()).isEqualTo("api.example.com");
        assertThat(echo.method()).isEqualTo("tempo");
        assertThat(echo.intent()).isEqualTo("charge");
        assertThat(echo.request()).isEqualTo("request-b64");
        assertThat(echo.expires()).isEqualTo("2099-01-01T00:00:00Z");
        assertThat(echo.digest()).isEqualTo("sha-256=abc");
        assertThat(echo.opaque()).isSameAs(opaque);
        assertThat(echo.opaqueRaw()).isEqualTo(
            ChallengeId.b64urlEncode(Json.compact(opaque))
        );
        assertThat(echo).isEqualTo(equivalent).hasSameHashCodeAs(equivalent);
    }

    @Test
    void challengeEchoCanPreserveRawOpaqueWithoutDecodedMetadata() {
        String opaque = ChallengeId.b64urlEncode("xy wrong");

        ChallengeEcho echo = ChallengeEcho.fromWire(
            "id", "realm", "tempo", "charge", "request", null, null,
            opaque, Parsing.decodeOpaque(opaque)
        );

        assertThat(echo.opaqueRaw()).isEqualTo(opaque);
        assertThat(echo.opaque()).isNull();
    }

    @Test
    void credentialPreservesRecordStyleApiAndValueSemantics() {
        ChallengeEcho echo = new ChallengeEcho("id", "realm", "tempo", "charge", "request", null, null, null);
        Map<String, Object> payload = Map.of("hash", "0xabc");
        Credential credential = new Credential(echo, payload, "0xsource");
        Credential equivalent = new Credential(echo, payload, "0xsource");

        assertThat(credential.challenge()).isSameAs(echo);
        assertThat(credential.payload()).isSameAs(payload);
        assertThat(credential.source()).isEqualTo("0xsource");
        assertThat(credential).isEqualTo(equivalent).hasSameHashCodeAs(equivalent);
    }

    @Test
    void receiptPreservesRecordStyleApiAndValueSemantics() {
        Instant timestamp = Instant.parse("2025-01-01T00:00:00Z");
        Map<String, Object> extra = Map.of("network", "tempo");
        Receipt receipt = new Receipt("success", timestamp, "ref", "tempo", "external", extra);
        Receipt equivalent = new Receipt("success", timestamp, "ref", "tempo", "external", extra);

        assertThat(receipt.status()).isEqualTo("success");
        assertThat(receipt.timestamp()).isSameAs(timestamp);
        assertThat(receipt.reference()).isEqualTo("ref");
        assertThat(receipt.method()).isEqualTo("tempo");
        assertThat(receipt.externalId()).isEqualTo("external");
        assertThat(receipt.extra()).isSameAs(extra);
        assertThat(receipt).isEqualTo(equivalent).hasSameHashCodeAs(equivalent);
    }

    @Test
    void verifyResultsPreserveRecordStyleApiAndValueSemantics() {
        ChallengeEcho echo = new ChallengeEcho("id", "realm", "tempo", "charge", "request", null, null, null);
        Challenge challenge = new Challenge("id", "tempo", "charge", null, "realm", "request", null, null, null, null);
        Credential credential = new Credential(echo, Map.of("hash", "0xabc"), null);
        Receipt receipt = new Receipt("success", Instant.parse("2025-01-01T00:00:00Z"), "ref", "tempo", null, null);

        VerifyResult.Challenged challenged = new VerifyResult.Challenged(challenge);
        VerifyResult.Challenged equivalentChallenged = new VerifyResult.Challenged(challenge);
        VerifyResult.Verified verified = new VerifyResult.Verified(credential, receipt);
        VerifyResult.Verified equivalentVerified = new VerifyResult.Verified(credential, receipt);

        assertThat(challenged.challenge()).isSameAs(challenge);
        assertThat(challenged).isEqualTo(equivalentChallenged).hasSameHashCodeAs(equivalentChallenged);
        assertThat(verified.credential()).isSameAs(credential);
        assertThat(verified.receipt()).isSameAs(receipt);
        assertThat(verified).isEqualTo(equivalentVerified).hasSameHashCodeAs(equivalentVerified);
    }

    @Test
    void validationResultPreservesRecordStyleApiAndValueSemantics() {
        ChallengeEcho echo = new ChallengeEcho(
            "id", "realm", "tempo", "charge", "request", null, null, null
        );
        Credential credential = new Credential(echo, Map.of("hash", "0xabc"), "payer");
        ValidationResult result = new ValidationResult(
            credential, Map.of("amount", "1"), Map.of("mode", "push")
        );
        ValidationResult equivalent = new ValidationResult(
            credential, Map.of("amount", "1"), Map.of("mode", "push")
        );

        assertThat(result.credential()).isSameAs(credential);
        assertThat(result.challenge()).isSameAs(echo);
        assertThat(result.request()).containsEntry("amount", "1");
        assertThat(result.details()).containsEntry("mode", "push");
        assertThat(result.method()).isEqualTo("tempo");
        assertThat(result.intent()).isEqualTo("charge");
        assertThat(result.source()).isEqualTo("payer");
        assertThat(result).isEqualTo(equivalent).hasSameHashCodeAs(equivalent);
    }
}

package com.stripe.mpp;

import org.junit.jupiter.api.Test;

import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class ParsingTest {

    // --- Challenge (WWW-Authenticate) ---

    @Test
    void challengeRoundTrips() {
        Map<String, Object> request = Map.of("amount", "10.000000", "currency", "USDC", "recipient", "0xABC");
        Challenge original = Challenge.create("secret", "example.com", "tempo", "charge", request,
            "2099-01-01T00:00:00Z", "Test payment", null);

        String header = original.toWwwAuthenticate();
        assertThat(header).startsWith("Payment ");
        assertThat(header).contains("id=");
        assertThat(header).contains("realm=\"example.com\"");
        assertThat(header).contains("method=\"tempo\"");
        assertThat(header).contains("intent=\"charge\"");
        assertThat(header).contains("expires=\"2099-01-01T00:00:00Z\"");
        assertThat(header).contains("description=\"Test payment\"");

        var parsed = Challenge.fromWwwAuthenticate(header);
        assertThat(parsed).hasSize(1);
        Challenge c = parsed.get(0);
        assertThat(c.id()).isEqualTo(original.id());
        assertThat(c.realm()).isEqualTo("example.com");
        assertThat(c.method()).isEqualTo("tempo");
        assertThat(c.intent()).isEqualTo("charge");
        assertThat(c.expires()).isEqualTo("2099-01-01T00:00:00Z");
    }

    @Test
    void challengeFromWwwAuthenticateHandlesMultipleSchemes() {
        // Only "Payment" schemes should be parsed
        String header = "Bearer foo, Payment id=\"abc\", realm=\"x\", method=\"tempo\", intent=\"charge\", request=\"e30\"";
        var challenges = Challenge.fromWwwAuthenticate(header);
        assertThat(challenges).hasSize(1);
        assertThat(challenges.get(0).id()).isEqualTo("abc");
    }

    @Test
    void challengeFromWwwAuthenticateHandlesMergedPaymentChallenges() {
        String first = "Payment id=\"one\", realm=\"api.example.com\", method=\"tempo\", intent=\"charge\", request=\"e30\"";
        String second = "Payment id=\"two\", realm=\"api.example.com\", method=\"stripe\", intent=\"charge\", request=\"e30\"";

        var challenges = Challenge.fromWwwAuthenticate(first + ", Bearer realm=\"fallback\", " + second);

        assertThat(challenges).hasSize(2);
        assertThat(challenges.get(0).id()).isEqualTo("one");
        assertThat(challenges.get(1).id()).isEqualTo("two");
    }

    @Test
    void challengeFromWwwAuthenticateIgnoresPaymentInsideQuotes() {
        String first = "Payment id=\"one\", realm=\"api, Payment realm\", method=\"tempo\", intent=\"charge\", request=\"e30\"";
        String second = "Payment id=\"two\", realm=\"api.example.com\", method=\"stripe\", intent=\"charge\", request=\"e30\"";

        var challenges = Challenge.fromWwwAuthenticate(first + ", " + second);

        assertThat(challenges).hasSize(2);
        assertThat(challenges.get(0).realm()).isEqualTo("api, Payment realm");
        assertThat(challenges.get(1).id()).isEqualTo("two");
    }

    @Test
    void challengeFromWwwAuthenticateAllowsWhitespaceAroundParamEquals() {
        String header = "Payment id=\"abc\", realm = \"api.example.com\", method=\"tempo\", intent=\"charge\", request=\"e30\"";

        var challenges = Challenge.fromWwwAuthenticate(header);

        assertThat(challenges).hasSize(1);
        assertThat(challenges.get(0).realm()).isEqualTo("api.example.com");
    }

    @Test
    void challengeFromWwwAuthenticateRejectsDuplicateParameters() {
        String header = "Payment id=\"abc\", realm=\"api.example.com\", method=\"tempo\", intent=\"charge\", request=\"e30\", id=\"def\"";

        assertThatThrownBy(() -> Challenge.fromWwwAuthenticate(header))
            .isInstanceOf(com.stripe.mpp.error.ParseException.class)
            .hasMessageContaining("Duplicate");
    }

    @Test
    void challengeEscapesQuotedStringDescription() {
        Challenge original = Challenge.create("secret", "example.com", "tempo", "charge", Map.of(),
            null, "Pay \"premium\" API", null);

