    @Test
    void tamperedChallengeIdForcesNewChallenge() {
        MppHandler server = Mpp.create(new TestMethod(), "api.example.com", "super-secret");
        Intent intent = new ChargeIntent();

        VerifyResult step1 = server.charge(null, intent, "10.000000", "USDC", "0xRecipient");
        Challenge challenge = ((VerifyResult.Challenged) step1).challenge();

        // Tamper with the challenge ID
        ChallengeEcho tamperedEcho = new ChallengeEcho(
            "TAMPERED_ID",
            challenge.realm(),
            challenge.method(),
            challenge.intent(),
            challenge.requestB64(),
            challenge.expires(),
            challenge.digest(),
            challenge.opaque()
        );
        Credential credential = new Credential(tamperedEcho, Map.of("sig", "x"), null);
        String authHeader = credential.toAuthorization();

        VerifyResult result = server.charge(authHeader, intent, "10.000000", "USDC", "0xRecipient");
        // Should return a new challenge, not verify
        assertThat(result).isInstanceOf(VerifyResult.Challenged.class);
    }

    @Test
    void wrongAmountForcesNewChallenge() {
        MppHandler server = Mpp.create(new TestMethod(), "api.example.com", "super-secret");
        Intent intent = new ChargeIntent();

        // Get challenge for 10 USDC
        VerifyResult step1 = server.charge(null, intent, "10.000000", "USDC", "0xRecipient");
        Challenge challenge = ((VerifyResult.Challenged) step1).challenge();

        // Build credential for 10 USDC challenge
        Credential credential = new Credential(challenge.toEcho(), Map.of("sig", "x"), null);
        String authHeader = credential.toAuthorization();

        // Try to use it for a 20 USDC request
        VerifyResult result = server.charge(authHeader, intent, "20.000000", "USDC", "0xRecipient");
        assertThat(result).isInstanceOf(VerifyResult.Challenged.class);
    }

    @Test
    void receiptRoundTripsViaHeader() {
        Receipt receipt = Receipt.success("ref-999", "test", "ext-111");
        String header = receipt.toPaymentReceipt();
        Receipt parsed = Receipt.fromPaymentReceipt(header);

        assertThat(parsed.status()).isEqualTo("success");
        assertThat(parsed.reference()).isEqualTo("ref-999");
        assertThat(parsed.method()).isEqualTo("test");
        assertThat(parsed.externalId()).isEqualTo("ext-111");
    }
}

package com.stripe.mpp;

import org.junit.jupiter.api.Test;

import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;

class ChallengeIdTest {

    @Test
    void generateIsDeteministic() {
        Map<String, Object> request = Map.of("amount", "10.000000", "currency", "USDC", "recipient", "0xABC");
        String id1 = ChallengeId.generate("secret", "example.com", "tempo", "charge", request, null, null, null);
        String id2 = ChallengeId.generate("secret", "example.com", "tempo", "charge", request, null, null, null);
        assertThat(id1).isEqualTo(id2);
    }

    @Test
    void generateDiffersWithDifferentKey() {
        Map<String, Object> request = Map.of("amount", "10.000000", "currency", "USDC", "recipient", "0xABC");
        String id1 = ChallengeId.generate("secret1", "example.com", "tempo", "charge", request, null, null, null);
        String id2 = ChallengeId.generate("secret2", "example.com", "tempo", "charge", request, null, null, null);
        assertThat(id1).isNotEqualTo(id2);
    }

    @Test
    void generateDiffersWithDifferentRealm() {
        Map<String, Object> request = Map.of("amount", "10.000000", "currency", "USDC", "recipient", "0xABC");
        String id1 = ChallengeId.generate("secret", "realm1.com", "tempo", "charge", request, null, null, null);
        String id2 = ChallengeId.generate("secret", "realm2.com", "tempo", "charge", request, null, null, null);
        assertThat(id1).isNotEqualTo(id2);
    }

    @Test
    void generateProducesBase64Url() {
        Map<String, Object> request = Map.of("amount", "10.000000", "currency", "USDC", "recipient", "0xABC");
        String id = ChallengeId.generate("secret", "example.com", "tempo", "charge", request, null, null, null);
        // Base64url uses - and _ instead of + and /, and has no padding (no =)
        assertThat(id).doesNotContain("+", "/", "=");
    }

    @Test
    void b64urlRoundTrip() {
        String original = "Hello, World!";
        String encoded = ChallengeId.b64urlEncode(original);
        byte[] decoded = ChallengeId.b64urlDecode(encoded);
        assertThat(new String(decoded)).isEqualTo(original);
    }

    @Test
    void generateWithExpires() {
        Map<String, Object> request = Map.of("amount", "10.000000", "currency", "USDC", "recipient", "0xABC");
        String withExpires    = ChallengeId.generate("secret", "example.com", "tempo", "charge", request, "2025-01-01T00:00:00Z", null, null);
        String withoutExpires = ChallengeId.generate("secret", "example.com", "tempo", "charge", request, null, null, null);
        assertThat(withExpires).isNotEqualTo(withoutExpires);
    }

    @Test
    void rawOpaqueUsesTheExactWireValue() {
        Map<String, Object> request = Map.of("amount", "10");
        Map<String, Object> meta = Map.of("route", "/paid");
        String opaque = ChallengeId.b64urlEncode(Json.compact(meta));

        assertThat(ChallengeId.generateWithOpaque(
            "secret", "example.com", "tempo", "charge", request, null, null, opaque
        )).isEqualTo(ChallengeId.generate(
            "secret", "example.com", "tempo", "charge", request, null, null, meta
        ));
        assertThat(ChallengeId.generateWithOpaque(
            "secret", "example.com", "tempo", "charge", request, null, null, "raw"
        )).isNotEqualTo(ChallengeId.generateWithOpaque(
            "secret", "example.com", "tempo", "charge", request, null, null, "RAW"
        ));
    }
}

